files.Counter.qnt:
// A counter that only climbs: the check project the Quint plugin is held to.
module Counter {
  var count: int

  action init = count' = 0
  action step = count' = count + 1

  // Holds in every state: the count never goes below where it started.
  val nonNegative = count >= 0
  // Broken within three steps: the count passes 2.
  val small = count < 3
}

files.edge/NoInit.qnt:
// A model with no initial state: init is never satisfied, so a simulation reaches nothing.
module NoInit {
  var count: int
  action init = all { count' = 0, false }
  action step = count' = count + 1
  val nonNegative = count >= 0
}

files.edge/Stuck.qnt:
// A model whose step is never enabled: every trace stops at its initial state.
module Stuck {
  var count: int
  action init = count' = 0
  action step = all { count > 5, count' = count + 1 }
  val nonNegative = count >= 0
}
